#include <bits/stdc++.h>
using namespace std;

#define P make_pair
#define range(x) (x).begin(), (x).end()
#define size(x) ((int)(x).size())
#define first f
#define second s
typedef long long ll;

mt19937 gen(chrono::steady_clock::now().time_since_epoch().count());
const int N = 12, INF = 1000000009;
const int dir_x[4] = {0, 1, 0, -1};
const int dir_y[4] = {1, 0, -1, 0};

struct Coord {
    int row, col;
    Coord() {}
    Coord(int _r, int _c) : row(_r), col(_c) {}
};

int n, t;
char mapA[N][N], mapB[N][N];

int start_x, start_y;
int distance_map[N][N];

void run_bfs(int d[N][N], int sx, int sy) {
    bool visited[N][N] = {};
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            d[i][j] = INF;
    queue<Coord> q;
    visited[sx][sy] = true;
    d[sx][sy] = 0;
    q.push(Coord(sx, sy));
    while (!q.empty()) {
        Coord curr = q.front(); q.pop();
        for (int d_idx = 0; d_idx < 4; ++d_idx) {
            Coord next_cell = curr;
            next_cell.row += dir_x[d_idx];
            next_cell.col += dir_y[d_idx];
            if (next_cell.row >= 0 && next_cell.row < n && next_cell.col >= 0 && next_cell.col < n
                && !visited[next_cell.row][next_cell.col]
                && mapA[next_cell.row][next_cell.col] >= '0'
                && mapA[next_cell.row][next_cell.col] <= '9') {
                visited[next_cell.row][next_cell.col] = true;
                d[next_cell.row][next_cell.col] = d[curr.row][curr.col] + 1;
                q.push(next_cell);
            }
        }
    }
}

bool residual[N * 6][N][N][N][N];
bool can_reach[N][N][N][N];

int g[2 * N * N][2 * N * N];

int p[2 * N * N];
bool visited_q[2 * N * N];

bool flow_bfs() {
    memset(visited_q, false, sizeof(visited_q));
    memset(p, 0, sizeof(p));
    queue<int> q;
    visited_q[0] = true;
    q.push(0);
    while (!q.empty()) {
        int curr_node = q.front(); q.pop();
        if (curr_node == 2 * n * n + 1)
            return true;
        for (int h = 0; h <= 2 * n * n + 1; ++h) {
            if (g[curr_node][h]) {
                if (!visited_q[h]) {
                    visited_q[h] = true;
                    p[h] = curr_node;
                    q.push(h);
                }
            }
        }
    }
    return false;
}

void process() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i)
        scanf(" %s", mapA[i]);
    for (int i = 0; i < n; ++i)
        scanf(" %s", mapB[i]);
    scanf("%d%d", &start_x, &start_y);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (mapA[i][j] == 'Z') {
                start_x = i; start_y = j;
            }
    run_bfs(distance_map, start_x, start_y);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if ('0' <= mapA[i][j] && mapA[i][j] <= '9')
                residual[0][i][j][i][j] = true;
    for (int step = 0; step < t; ++step) {
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y) {
                        if (!residual[step][sx][sy][x][y]) continue;
                        if (distance_map[x][y] <= step) continue;
                        for (int d_idx = 0; d_idx < 4; ++d_idx) {
                            int hx = x + dir_x[d_idx];
                            int hy = y + dir_y[d_idx];
                            if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= mapA[hx][hy] && mapA[hx][hy] <= '9') {
                                if (distance_map[hx][hy] >= step + 1)
                                    residual[step + 1][sx][sy][hx][hy] = true;
                            }
                        }
                    }
    }
    for (int step = 0; step <= t; ++step)
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (residual[step][sx][sy][x][y])
                            can_reach[sx][sy][x][y] = true;

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            if ('0' <= mapA[x1][y1] && mapA[x1][y1] <= '9')
                g[0][x1 * n + y1 + 1] = mapA[x1][y1] - '0';

    for (int x2 = 0; x2 < n; ++x2)
        for (int y2 = 0; y2 < n; ++y2)
            if ('0' <= mapB[x2][y2] && mapB[x2][y2] <= '9')
                g[n * n + x2 * n + y2 + 1][2 * n * n + 1] = mapB[x2][y2] - '0';

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            for (int x2 = 0; x2 < n; ++x2)
                for (int y2 = 0; y2 < n; ++y2) {
                    if (!('0' <= mapA[x1][y1] && mapA[x1][y1] <= '9')) continue;
                    if (!('0' <= mapA[x2][y2] && mapA[x2][y2] <= '9')) continue;
                    if (!can_reach[x1][y1][x2][y2]) continue;
                    g[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                }

    while (flow_bfs()) {
        int flow_val = INF;
        for (int i = 2 * n * n + 1; i; i = p[i]) {
            flow_val = min(flow_val, g[p[i]][i]);
        }
        for (int i = 2 * n * n + 1; i; i = p[i]) {
            g[p[i]][i] -= flow_val;
            g[i][p[i]] += flow_val;
        }
    }

    int total = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i)
        total += g[i][0];

    printf("%d\n", total);
}

int main() {
    #ifdef SOMETHING
    freopen("input.txt", "r", stdin);
    #endif
    process();
    return 0;
}
